/* 等价 C 语言参考：死锁检测（资源分配图可完全化简） */
#include <stdio.h>
#include <stdbool.h>

#define MAXN 16
#define MAXM 16

/* available[0..m-1]；allocation / request 为 [n][m]；返回未完成进程个数，dead[] 输出其下标 */
int detect(int n, int m, int available[], int allocation[][MAXM],
           int request[][MAXM], int dead[]) {
    int work[MAXM];
    bool finish[MAXN];
    for (int j = 0; j < m; j++) work[j] = available[j];
    for (int i = 0; i < n; i++) finish[i] = false;

    while (true) {
        bool progressed = false;
        for (int i = 0; i < n; i++) {
            if (finish[i]) continue;
            bool ok = true;
            for (int j = 0; j < m; j++) {
                if (request[i][j] > work[j]) { ok = false; break; }
            }
            if (ok) {
                for (int j = 0; j < m; j++) work[j] += allocation[i][j];
                finish[i] = true;
                progressed = true;
                break;
            }
        }
        if (!progressed) break;
    }

    int cnt = 0;
    for (int i = 0; i < n; i++)
        if (!finish[i]) dead[cnt++] = i;   /* 未完成者即死锁进程 */
    return cnt;
}

int main(void) {
    int available[2] = {0, 0};
    int allocation[2][MAXM] = {{1,0},{0,1}};
    int request[2][MAXM] = {{0,1},{1,0}};
    int dead[2];
    int cnt = detect(2, 2, available, allocation, request, dead);
    printf("deadlocked (%d): ", cnt);
    for (int i = 0; i < cnt; i++) printf("%d ", dead[i]);
    printf("\n");
    return 0;
}

