def solve(available, allocation, request):
    """死锁检测（资源分配图可完全化简则无死锁）。

    available: 一维资源向量（长度 m）。
    allocation / request: [进程数][资源数] 的二维列表（request 为尚需/请求量）。
    返回: 最终未完成（死锁）的进程下标列表，升序；无死锁返回 []。
    """
    n = len(allocation)
    m = len(available)
    work = list(available)
    finish = [False] * n

    while True:
        progressed = False
        for i in range(n):
            if finish[i]:
                continue
            if all(request[i][j] <= work[j] for j in range(m)):
                for j in range(m):
                    work[j] += allocation[i][j]   # 进程 i 完成，归还其占用的资源
                finish[i] = True
                progressed = True
                break
        if not progressed:
            break

    return sorted(i for i in range(n) if not finish[i])
